export const KIND = {"id":69,"example":{"id":"E69","kind":69,"source":"aether","statement":["Write a class `columns::grid` whose constructor takes a `const std::string& text` and a width as an `int`, and whose member `by_columns()` returns a `std::string`.","The object keeps only the letters and digits of text, in order, the letters made lowercase.","Written row by row in rows of width characters, the last row maybe shorter, the kept characters are read column by column, left to right, each column from top to bottom.","`by_columns()` returns the characters in that order, with no spaces.","Limits: 1 ≤ width ≤ 20; 0 ≤ length of text ≤ 200; each character is ASCII."],"examples":[],"tests":[],"solution":{"lines":["#pragma once","","#include <cctype>","#include <string>","","namespace columns {","","class grid {","    std::string text_ {};","    int width_ {1};","public:","    grid(const std::string& text, int width)","        : width_ {width}","    {","        for (const unsigned char sign : text) {","            if (std::isalnum(sign)) {","                text_ += static_cast<char>(std::tolower(sign));","            }","        }","    }","    std::string by_columns() const","    {","        std::string result {\"\"};","        for (int column {0}; column < width_; ++column) {","            for (int index {column}; index < std::ssize(text_);","                 index += width_) {","                result += text_[index];","            }","        }","        return result;","    }","};","","}  // namespace columns"],"frame":[0,2,3,5,31,33],"labels":[{"at":7,"level":1,"text":"Write a class that keeps its data in private members."},{"at":11,"level":1,"text":"Write a constructor that sets the data."},{"at":14,"level":2,"text":"Keep each letter, made lowercase, and each digit of the text, in order."},{"at":14,"level":0,"text":"Read each character as an `unsigned char`, the form the `cctype` tests take."},{"at":15,"level":0,"text":"Test whether a character is a letter or a digit with `std::isalnum`."},{"at":20,"level":1,"text":"Write a member function that builds a new string one piece at a time and gives it back."},{"at":22,"level":2,"text":"Start the result as an empty string."},{"at":23,"level":2,"text":"For each column, add its character in each row that reaches it."},{"at":29,"level":2,"text":"Give back the result."}],"blanks":[]}},"trace":{"id":"T69","lines":["#include <iostream>","#include <print>","#include <string>","int main()","{","    std::string text {};","    int width {0};","    std::cin >> text >> width;","    for (int column {0}; column < width; ++column) {","        std::string line {};","        for (int index {column}; index < std::ssize(text);","             index += width) {","            line += text[index];","        }","        std::println(\"{}\", line);","    }","}"],"columns":["text","width","column","line","index"],"inputs":["ab 1\n","abcdefg 3\n"],"rows":[{"line":6,"values":["","","","",""]},{"line":7,"values":["","0","","",""]},{"line":8,"values":["ab","1","","",""]},{"line":9,"values":["ab","1","0","",""]},{"line":10,"values":["ab","1","0","",""]},{"line":11,"values":["ab","1","0","","0"]},{"line":13,"values":["ab","1","0","a","0"]},{"line":12,"values":["ab","1","0","a","1"]},{"line":11,"values":["ab","1","0","a","1"]},{"line":13,"values":["ab","1","0","ab","1"]},{"line":12,"values":["ab","1","0","ab","2"]},{"line":11,"values":["ab","1","0","ab",""]},{"line":15,"values":["ab","1","0","ab",""]},{"line":9,"values":["ab","1","","",""]}],"output":"adg\nbe\ncf\n"},"traces":[],"problems":{"69.01":{"id":"69.01","kind":69,"source":"exercism","statement":["Write a class `crypto_square::cipher` whose constructor takes a `const std::string& text`, and whose member `normalized_cipher_text()` returns text coded as follows, as a `std::string`.","Keep only the letters and digits of text, in order, the letters made lowercase; say n characters are left.","The number of columns c is the smallest number with c × c ≥ n, and the number of rows r is the smallest with r × c ≥ n.","Write the characters row by row into r rows of c, and fill the end of the last row with spaces.","Return the columns, left to right, each read from top to bottom, with one space between 2 columns.","When no characters are left, return an empty string.","Limits: none"],"examples":[{"input":"empty plaintext results in an empty ciphertext","output":""}],"tests":[{"input":"normalization results in empty plaintext","output":""},{"input":"Lowercase","output":""},{"input":"Remove spaces","output":""},{"input":"Remove punctuation","output":""},{"input":"9 character plaintext results in 3 chunks of 3 characters","output":""},{"input":"8 character plaintext results in 3 chunks, the last one with a trailing space","output":""},{"input":"54 character plaintext results in 8 chunks, the last two with trailing spaces","output":""}],"solution":{"lines":["#pragma once","","#include <cctype>","#include <string>","","namespace crypto_square {","","class cipher {","    std::string text_ {};","public:","    explicit cipher(const std::string& text)","    {","        for (const unsigned char sign : text) {","            if (std::isalnum(sign)) {","                text_ += static_cast<char>(std::tolower(sign));","            }","        }","    }","    std::string normalized_cipher_text() const","    {","        const int size {static_cast<int>(text_.size())};","        int columns {0};","        while (columns * columns < size) {","            ++columns;","        }","        int rows {0};","        while (rows * columns < size) {","            ++rows;","        }","        std::string result {\"\"};","        for (int column {0}; column < columns; ++column) {","            if (column > 0) {","                result += ' ';","            }","            for (int row {0}; row < rows; ++row) {","                const int index {row * columns + column};","                result += index < size ? text_[index] : ' ';","            }","        }","        return result;","    }","};","","}  // namespace crypto_square"],"frame":[0,2,3,5,41,43],"labels":[{"at":7,"level":1,"text":"Write a class that keeps its data in private members."},{"at":10,"level":1,"text":"Write a constructor that sets the data."},{"at":12,"level":2,"text":"Keep each letter, made lowercase, and each digit of the text, in order."},{"at":18,"level":1,"text":"Write a member function that builds a new string one piece at a time and gives it back."},{"at":20,"level":2,"text":"Find the columns, the smallest number whose square is at least the size."},{"at":25,"level":2,"text":"Find the rows, the smallest number that times the columns is at least the size."},{"at":29,"level":2,"text":"Start the result as an empty string."},{"at":30,"level":2,"text":"For each column, add a space before all but the first, then its character in each row, or a space past the end."},{"at":39,"level":2,"text":"Give back the result."}],"blanks":[{"line":8,"from":22,"to":24},{"line":10,"from":20,"to":43},{"line":13,"from":16,"to":34},{"line":18,"from":4,"to":15},{"line":22,"from":15,"to":39},{"line":26,"from":15,"to":36},{"line":29,"from":28,"to":30},{"line":36,"from":26,"to":38},{"line":39,"from":15,"to":21}]},"fn":{"slug":"crypto-square","commit":"8d139cb0","header":"crypto_square.h","name":"crypto_square_test.cpp","test":"#include \"crypto_square.h\"\n#ifdef EXERCISM_TEST_SUITE\n#include <catch2/catch.hpp>\n#else\n#include \"test/catch.hpp\"\n#endif\n\nTEST_CASE(\"empty plaintext results in an empty ciphertext\",\n          \"[407c3837-9aa7-4111-ab63-ec54b58e8e9f]\") {\n    REQUIRE(\"\" == crypto_square::cipher(\"\").normalized_cipher_text());\n}\n\n#if defined(EXERCISM_RUN_ALL_TESTS)\nTEST_CASE(\"normalization results in empty plaintext\",\n          \"[aad04a25-b8bb-4304-888b-581bea8e0040]\") {\n    REQUIRE(\"\" ==\n            crypto_square::cipher(\"... --- ...\").normalized_cipher_text());\n}\n\nTEST_CASE(\"Lowercase\", \"[64131d65-6fd9-4f58-bdd8-4a2370fb481d]\") {\n    REQUIRE(\"a\" == crypto_square::cipher(\"A\").normalized_cipher_text());\n}\n\nTEST_CASE(\"Remove spaces\", \"[63a4b0ed-1e3c-41ea-a999-f6f26ba447d6]\") {\n    REQUIRE(\"b\" == crypto_square::cipher(\"  b \").normalized_cipher_text());\n}\n\nTEST_CASE(\"Remove punctuation\", \"[1b5348a1-7893-44c1-8197-42d48d18756c]\") {\n    REQUIRE(\"1\" == crypto_square::cipher(\"@1,%!\").normalized_cipher_text());\n}\n\nTEST_CASE(\"9 character plaintext results in 3 chunks of 3 characters\",\n          \"[8574a1d3-4a08-4cec-a7c7-de93a164f41a]\") {\n    REQUIRE(\"tsf hiu isn\" ==\n            crypto_square::cipher(\"This is fun!\").normalized_cipher_text());\n}\n\nTEST_CASE(\n    // clang-format off\n    \"8 character plaintext results in 3 chunks, the last one with a trailing space\",\n    // clang-format on\n    \"[a65d3fa1-9e09-43f9-bcec-7a672aec3eae]\") {\n    REQUIRE(\"clu hlt io \" ==\n            crypto_square::cipher(\"Chill out.\").normalized_cipher_text());\n}\n\nTEST_CASE(\n    // clang-format off\n    \"54 character plaintext results in 8 chunks, the last two with trailing spaces\",\n    // clang-format on\n    \"[33fd914e-fa44-445b-8f38-ff8fbc9fe6e6]\") {\n    REQUIRE(\"imtgdvs fearwer mayoogo anouuio ntnnlvt wttddes aohghn  sseoau \" ==\n            crypto_square::cipher(\"If man was meant to stay on the ground, god \"\n                                  \"would have given us roots.\")\n                .normalized_cipher_text());\n}\n#endif\n","setup":[],"calls":[{"call":"crypto_square::cipher(\"\").normalized_cipher_text()","expected":"\"\""}]}},"69.02":{"id":"69.02","kind":69,"source":"aether","statement":["Write a class `column_reader::reader` whose constructor takes a `const std::string& text` and a width as an `int`, and whose member `column(int index)` returns a `std::string`.","The object keeps only the letters of text, in order, made uppercase.","Written row by row in rows of width letters, the last row maybe shorter, `column(index)` returns the letters of column index from top to bottom, counting the first column as 0.","Limits: 1 ≤ width ≤ 20; 0 ≤ index < width; 0 ≤ length of text ≤ 200; each character is ASCII."],"examples":[{"input":"second_column","output":""}],"tests":[{"input":"empty_text","output":""},{"input":"first_column_of_a_short_last_row","output":""},{"input":"last_column","output":""},{"input":"only_letters_are_kept","output":""},{"input":"width_1","output":""},{"input":"width_larger_than_the_text","output":""},{"input":"text_with_no_letters","output":""},{"input":"longest_text","output":""}],"solution":{"lines":["#pragma once","","#include <cctype>","#include <string>","","namespace column_reader {","","class reader {","    std::string text_ {};","    int width_ {1};","public:","    reader(const std::string& text, int width)","        : width_ {width}","    {","        for (const unsigned char sign : text) {","            if (std::isalpha(sign)) {","                text_ += static_cast<char>(std::toupper(sign));","            }","        }","    }","    std::string column(int index) const","    {","        std::string result {\"\"};","        for (int at {index}; at < std::ssize(text_);","             at += width_) {","            result += text_[at];","        }","        return result;","    }","};","","}  // namespace column_reader"],"frame":[0,2,3,5,29,31],"labels":[{"at":7,"level":1,"text":"Write a class that keeps its data in private members."},{"at":11,"level":1,"text":"Write a constructor that sets the data."},{"at":14,"level":2,"text":"Keep each letter of the text, made uppercase, in order."},{"at":20,"level":1,"text":"Write a member function that builds a new string one piece at a time and gives it back."},{"at":22,"level":2,"text":"Start the result as an empty string."},{"at":23,"level":2,"text":"Add every letter from the index on, one row apart."},{"at":27,"level":2,"text":"Give back the result."}],"blanks":[{"line":8,"from":22,"to":24},{"line":12,"from":18,"to":23},{"line":15,"from":16,"to":34},{"line":20,"from":23,"to":32},{"line":22,"from":28,"to":30},{"line":25,"from":22,"to":30},{"line":27,"from":15,"to":21}]},"fn":{"slug":"column_reader","commit":"","header":"column_reader.h","name":"column_reader_test.cpp","test":"#include \"column_reader.h\"\n#include \"test/catch.hpp\"\n\nTEST_CASE(\"second_column\") {\n    const column_reader::reader grid {\"abcdefg\", 3};\n    REQUIRE(grid.column(1) == \"BE\");\n}\n#if defined(EXERCISM_RUN_ALL_TESTS)\nTEST_CASE(\"empty_text\") {\n    const column_reader::reader grid {\"\", 4};\n    REQUIRE(grid.column(0) == \"\");\n}\nTEST_CASE(\"first_column_of_a_short_last_row\") {\n    const column_reader::reader grid {\"abcdefg\", 3};\n    REQUIRE(grid.column(0) == \"ADG\");\n}\nTEST_CASE(\"last_column\") {\n    const column_reader::reader grid {\"abcdefg\", 3};\n    REQUIRE(grid.column(2) == \"CF\");\n}\nTEST_CASE(\"only_letters_are_kept\") {\n    const column_reader::reader grid {\"a1 b-c, d!E?f\", 2};\n    REQUIRE(grid.column(0) == \"ACE\");\n    REQUIRE(grid.column(1) == \"BDF\");\n}\nTEST_CASE(\"width_1\") {\n    const column_reader::reader grid {\"Hi there\", 1};\n    REQUIRE(grid.column(0) == \"HITHERE\");\n}\nTEST_CASE(\"width_larger_than_the_text\") {\n    const column_reader::reader grid {\"abc\", 20};\n    REQUIRE(grid.column(1) == \"B\");\n    REQUIRE(grid.column(19) == \"\");\n}\nTEST_CASE(\"text_with_no_letters\") {\n    const column_reader::reader grid {\"123 456\", 2};\n    REQUIRE(grid.column(1) == \"\");\n}\nTEST_CASE(\"longest_text\") {\n    std::string text {};\n    for (int i {0}; i < 200; ++i) {\n        text += static_cast<char>('a' + i % 26);\n    }\n    const column_reader::reader grid {text, 20};\n    REQUIRE(grid.column(0) == \"AUOICWQKEY\");\n}\n#endif\n","setup":["const column_reader::reader grid {\"abcdefg\", 3};"],"calls":[{"call":"grid.column(1)","expected":"\"BE\""}]}}}}
